begin;

-- New categories for the actual retail catalogue that were not in the original demo schema.
on conflict (id) do update set code = excluded.code, name = excluded.name, active = true;

-- A supplier placeholder for this opening-balance import (actual supplier records can replace it later).
on conflict (id) do update set name = excluded.name, active = true;

-- Wipe every demo/sample product, variant, cost, and transaction so only the real catalogue remains.
delete from public.sale_lines;
delete from public.sales;
delete from public.inventory_transaction_lines;
delete from public.inventory_transactions;
delete from public.purchase_charges;
delete from public.purchase_invoices;
delete from public.variant_cost_history;
delete from public.variant_private_costs;
delete from public.product_variants;
delete from public.products;























































